export function getBrandIcon(nameOrKey?: string | null): BrandIconData | undefined {
  if (!nameOrKey) return undefined;
  const normalized = nameOrKey
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]/g, '');

  // Exact match
  if (BRAND_ICONS[nameOrKey.toLowerCase().trim()]) {
    return BRAND_ICONS[nameOrKey.toLowerCase().trim()];
  }

  // Normalized key match
  for (const [key, icon] of Object.entries(BRAND_ICONS)) {
    const normKey = key.replace(/[^a-z0-9]/g, '');
    if (normKey === normalized || normalized.includes(normKey) || normKey.includes(normalized)) {
      return icon;
    }
  }

  return undefined;
}
